package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class ReferenceType_getGenericSignature_TriageGen2Test {

    /**
     * Since ReferenceType has protected constructors and relies on internal state 
     * like _class, _referencedType, and the method _classSignature, 
     * we use Mockito to mock the behavior of the instance or its dependencies.
     * 
     * Note: In a real Jackson environment, ReferenceType is often constructed via 
     * ReferenceType.construct(). To test this specific method logic (which is 
     * essentially a sequence of appends), we mock the object to control the 
     * side effects of the internal calls.
     */
    @Test
    public void testGetGenericSignature_Success() {
        // Arrange
        StringBuilder sb = new StringBuilder("Initial");

        // We need to mock ReferenceType to bypass the protected constructor constraints 
        // and control the internal method calls: _classSignature and _referencedType.getGenericSignature
        ReferenceType mockReferenceType = mock(ReferenceType.class, Mockito.CALLS_REAL_METHODS);
        JavaType mockReferencedType = mock(JavaType.class);

        // Setup the internal state via mocking behavior
        // Note: Because _classSignature and _referencedType are internal fields, 
        // we simulate the behavior of the method being tested.

        // Mock the behavior of _referencedType.getGenericSignature(sb)
        when(mockReferencedType.getGenericSignature(any(StringBuilder.class))).thenAnswer(invocation -> {
            StringBuilder passedSb = invocation.getArgument(0);
            passedSb.append("MockedType");
            return passedSb;
        });

        // Since we cannot easily inject into private fields of a real object without reflection,
        // we simulate the method logic by overriding the specific calls if possible, 
        // or by using a spy on a real instance if we can construct it.

        // Given the constraints of the provided code snippet:
        // 1. _classSignature(_class, sb, false);
        // 2. sb.append('<');
        // 3. sb = _referencedType.getGenericSignature(sb);
        // 4. sb.append(">;");

        // We will use a Spy to simulate the internal calls.
        ReferenceType spyRefType = spy(mockReferenceType);

        // We simulate the field _referencedType by making sure the spy returns a mock when getReferencedType is called,
        // but since the code uses the field directly, we must mock the method that uses the field or use reflection.
        // For a pure unit test of the method logic:

        // Let's assume we use reflection to set the private fields to ensure we are testing the actual method body.
        try {
            java.lang.reflect.Field refField = ReferenceType.class.getDeclaredField("_referencedType");
            refField.setAccessible(true);
            refField.set(spyRefType, mockReferencedType);

            java.lang.reflect.Field classField = ReferenceType.class.getDeclaredField("_class");
            classField.setAccessible(true);
            classField.set(spyRefType, String.class);

            // Mocking the internal _classSignature method call via spy
            // Since _classSignature is likely a private/protected method, we simulate its effect on sb
            doAnswer(invocation -> {
                StringBuilder s = invocation.getArgument(1);
                s.append("ClassSignature");
                return null;
            }).when(spyRefType)._classSignature(any(), any(StringBuilder.class), anyBoolean());

            // The method _classSignature is actually defined in the class. 
            // If it's not available to mock directly via spy (if private), 
            // we rely on the fact that we are testing the sequence of SB operations.

        } catch (Exception e) {
            throw new RuntimeException(e);
        }

        // Act
        StringBuilder result = spyRefType.getGenericSignature(sb);

        // Assert
        // Expected sequence: 
        // 1. "Initial" + "ClassSignature" (from _classSignature)
        // 2. "ClassSignature<"
        // 3. "ClassSignature<MockedType" (from _referencedType.getGenericSignature)
        // 4. "ClassSignature<MockedType>;"
        String expected = "InitialClassSignature<MockedType>;";
        assertEquals(expected, result.toString());

        verify(mockReferencedType, times(1)).getGenericSignature(any(StringBuilder.class));
    }

    @Test
    public void testGetGenericSignature_EmptyStringBuilder() {
        // Arrange
        StringBuilder sb = new StringBuilder();
        ReferenceType spyRefType = spy(mock(ReferenceType.class, Mockito.CALLS_REAL_METHODS));
        JavaType mockReferencedType = mock(JavaType.class);

        try {
            java.lang.reflect.Field refField = ReferenceType.class.getDeclaredField("_referencedType");
            refField.setAccessible(true);
            refField.set(spyRefType, mockReferencedType);

            doAnswer(invocation -> {
                StringBuilder s = invocation.getArgument(1);
                s.append("Type");
                return null;
            }).when(spyRefType)._classSignature(any(), any(StringBuilder.class), anyBoolean());

            when(mockReferencedType.getGenericSignature(any(StringBuilder.class))).thenAnswer(inv -> inv.getArgument(0));
        } catch (Exception e) {
            throw new RuntimeException(e);
        }

        // Act
        StringBuilder result = spyRefType.getGenericSignature(sb);

        // Assert
        // 1. "" + "Signature" (from _classSignature)
        // 2. "Signature<"
        // 3. "Signature<Type"
        // 4. "Signature<Type>;"
        assertEquals("Signature<Type>;", result.toString());
    }
}
